         padding: 0.95rem 1.35rem;
         background: linear-gradient(135deg, var(--accent-strong), #60a5fa);
         color: #04101e;
         font: inherit;
         font-weight: 800;
         box-shadow: 0 14px 30px rgba(56, 189, 248, 0.28);
         cursor: pointer;
         transition: transform 0.18s ease, box-shadow 0.18s ease;
       }

       .submit-button:hover {
         transform: translateY(-1px);
         box-shadow: 0 18px 34px rgba(56, 189, 248, 0.34);
       }

       .submit-button:focus-visible {
         outline: 3px solid rgba(125, 211, 252, 0.45);
         outline-offset: 3px;
       }

       .form-status {
         margin: 0;
         color: var(--muted);
         line-height: 1.5;
       }

       @media (max-width: 520px) {
         .page-shell {
           padding-inline: 0.75rem;
         }

         .panel {
           border-radius: 16px;
         }
       }

       @media (prefers-reduced-motion: reduce) {
         html {
           scroll-behavior: auto;
         }

         *,
         *::before,
         *::after {
           animation-duration: 0.01ms !important;
           animation-iteration-count: 1 !important;
           transition-duration: 0.01ms !important;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="app"></div>

     <script>
       const app = document.getElementById('app');

       const field = ({ id, label, required, type, autocomplete, help, inputMode }) => `
         <div class="form-field">
           <label for="${id}">
             ${label}${required ? ' <span class="required-mark" aria-hidden="true">*</span>' : ''}
           </label>
           <input
             id="${id}"
             name="${id}"
             type="${type}"
             ${required ? 'required' : ''}
             autocomplete="${autocomplete}"
             ${inputMode ? `inputmode="${inputMode}"` : ''}
             aria-describedby="${id}-help ${id}-error"
           >
           <p class="field-help" id="${id}-help">${help}</p>
           <p class="field-error" id="${id}-error" hidden></p>
         </div>
       `;

       app.innerHTML = `
         <div class="page-shell">
           <header class="hero">
             <p class="eyebrow">Support</p>
             <h1>Contact our support team</h1>
             <p class="hero-copy">Send us your full name, email address, and phone number so we can follow up quickly and accurately.</p>
           </header>

           <main id="main-content" tabindex="-1">
             <section class="panel" aria-labelledby="contact-form-title">
               <div class="panel-header">
                 <h2 id="contact-form-title">Send a message</h2>
                 <p>Fields marked with an asterisk are required. Phone number is optional.</p>
               </div>

               <form id="support-form" novalidate>
                 <div class="form-grid">
                   ${field({
                     id: 'full-name',
                     label: 'Full name',
                     required: true,
                     type: 'text',
                     autocomplete: 'name',
                     help: 'Use the name you want support to use when replying.'
                   })}

                   ${field({
                     id: 'email-address',
                     label: 'Email address',
                     required: true,
                     type: 'email',
                     autocomplete: 'email',
                     help: 'We will reply to this address.'
                   })}

                   ${field({
                     id: 'phone-number',
                     label: 'Phone number',
                     required: false,
                     type: 'tel',
                     autocomplete: 'tel',
                     inputMode: 'tel',
                     help: 'Optional. Use a format like +1 555 123 4567 or (555) 123-4567.'
                   })}
                 </div>

                 <div class="form-actions">
                   <button class="submit-button" type="submit">Send message</button>
                   <p class="form-status" id="form-status" role="status" aria-live="polite"></p>
                 </div>
               </form>
             </section>
           </main>
         </div>
       `;

       const form = document.getElementById('support-form');
       const status = document.getElementById('form-status');
       const inputs = Array.from(form.querySelectorAll('input'));
       const touched = new Set();

       const validators = {
         'full-name': value => {
           if (!value.trim()) return 'Error: Enter your full name.';
           return '';
         },
         'email-address': value => {
           if (!value.trim()) return 'Error: Enter your email address.';
           return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
             ? ''
             : 'Error: Enter a valid email address like name@example.com.';
         },
         'phone-number': value => {
           const trimmed = value.trim();
           if (!trimmed) return '';
           return /^[+()\d\s.-]{7,}$/.test(trimmed) && /\d/.test(trimmed)
             ? ''
             : 'Error: Enter a phone number using digits and separators like +1 555 123 4567.';
         }
       };

       function updateFieldState(input, forceShowError = false) {
         const errorId = `${input.id}-error`;
         const errorEl = document.getElementById(errorId);
         const message = validators[input.id](input.value);
         const showError = forceShowError || touched.has(input.id);

         if (message && showError) {
           input.setAttribute('aria-invalid', 'true');
           errorEl.textContent = message;
           errorEl.hidden = false;
           return false;
         }

         input.removeAttribute('aria-invalid');
         errorEl.textContent = '';
         errorEl.hidden = true;
         return !message;
       }

       function validateForm() {
         let firstInvalid = null;
         let isValid = true;

         for (const input of inputs) {
           touched.add(input.id);
           const fieldValid = updateFieldState(input, true);

           if (!fieldValid && !firstInvalid) {
             firstInvalid = input;
           }

           isValid = isValid && fieldValid;
         }

         return { isValid, firstInvalid };
       }

       form.addEventListener('submit', event => {
         event.preventDefault();
         status.textContent = '';

         const { isValid, firstInvalid } = validateForm();

         if (!isValid) {
           status.textContent = 'Please fix the highlighted fields before sending.';
           firstInvalid.focus();
           return;
         }

         status.textContent = 'Your details look good and are ready to send.';
         form.reset();
         touched.clear();

         for (const input of inputs) {
           updateFieldState(input, false);
         }
       });

       for (const input of inputs) {
         input.addEventListener('blur', () => {
           touched.add(input.id);
           updateFieldState(input, true);
         });

         input.addEventListener('input', () => {
           if (touched.has(input.id)) {
             updateFieldState(input, false);
           }
         });
       }
     </script>
   </body>
 </html>

')

